#!/usr/bin/env python3
import json
from pathlib import Path

names = []

def add(name, gender, origins, themes, etymology, meaning, hidden, syllables, vibe, tags=None):
    nid = "".join(c if c.isalnum() else "-" for c in name.lower().strip())
    while "--" in nid:
        nid = nid.replace("--", "-")
    nid = nid.strip("-")
    names.append({
        "id": nid,
        "name": name.strip(),
        "gender": gender,
        "origins": origins,
        "themes": themes,
        "etymology": etymology,
        "meaning": meaning,
        "hiddenMeaning": hidden,
        "syllables": syllables,
        "length": len(name.strip()),
        "vibe": vibe,
        "tags": tags or [],
    })

