# Deduplicate and write
seen = set()
unique = []
for n in names:
    if n["id"] not in seen:
        seen.add(n["id"])
        unique.append(n)

out = Path("/workspace/namey/src/data/names.json")
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(unique, indent=2, ensure_ascii=False) + "\n")
print("Wrote", len(unique), "names")
print("Boy:", sum(1 for n in unique if n["gender"] == "boy"))
print("Girl:", sum(1 for n in unique if n["gender"] == "girl"))
print("Unisex:", sum(1 for n in unique if n["gender"] == "unisex"))
